// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address,uint256 _value) public {
        vm.assume(_value <= address(c).balance / 2);
        uint256 preOwnerBalance = c.owner().balance;
        c.sendMoney(address(0), _value);
        assertTrue(c.owner().balance == preOwnerBalance + _value);
    }
}

